insert into campaigns (id,nome,titulo,texto,ativa,ordem) values ('15-anos','Aniversário de 15 anos','Seus 15 anos em um lugar mágico','Que tal comemorar seus 15 anos em um dos destinos mais mágicos do mundo? Transforme essa data especial em uma lembrança inesquecível.',true,3) on conflict (id) do nothing;
