insert into campaigns (id,nome,titulo,texto,ativa,ordem) values ('praias','Praias','Mar, sol e pé na areia','Águas claras, areia macia e dias que parecem não ter fim. Escolha o seu mar e deixe o resto com a gente.',true,4) on conflict (id) do nothing;
