insert into destination_contents (destino_id,titulo_emocional,texto,motivos,faq) values ('italia','Gastronomia, história e paisagens apaixonantes','Gastronomia, história e paisagens apaixonantes. Descubra a Itália e crie memórias que acompanharão você para sempre. Roma é o ponto de partida perfeito: de lá, trens rápidos levam a Florença, Veneza e à Costa Amalfitana.','["Roma, Florença e Veneza a poucas horas de trem entre si","Uma das cozinhas mais amadas do planeta","Primavera com clima agradável para caminhar pelas cidades","Arte e arquitetura em cada esquina"]'::jsonb,'[{"p":"Este preço está garantido?","r":"Não. As tarifas aéreas mudam conforme a disponibilidade. O valor mostrado é o encontrado na data da pesquisa e é confirmado pelo consultor no momento da sua solicitação."},{"p":"O que está incluído?","r":"Esta é uma oferta de passagem aérea de ida e volta para um adulto, em classe econômica. Hospedagem e outros serviços podem ser cotados à parte com o consultor."},{"p":"Posso mudar as datas?","r":"Sim. Informe as datas que você prefere e o consultor procura a melhor combinação disponível — o valor pode ser diferente do anunciado."},{"p":"Preciso de passaporte ou visto?","r":"As exigências de entrada mudam com frequência e dependem da sua nacionalidade. Nosso consultor confirma os documentos necessários antes da emissão."},{"p":"Como funciona o parcelamento?","r":"O valor pode ser dividido no cartão, conforme as condições vigentes no dia da emissão. O consultor informa as opções, inclusive para pagamento via Pix."}]'::jsonb) on conflict (destino_id) do nothing;
insert into destination_contents (destino_id,titulo_emocional,texto,motivos,faq) values ('portugal','Lisboa te espera de braços abertos','Ladeiras, azulejos, pastéis de nata e o pôr do sol no Tejo. Portugal fala a nossa língua e recebe brasileiros como poucos lugares no mundo — perfeito para a primeira viagem à Europa.','["Idioma em comum e muita afinidade cultural","Porta de entrada fácil para o resto da Europa","Gastronomia e vinhos com ótimo custo-benefício","Praias do Algarve a poucas horas de Lisboa"]'::jsonb,'[{"p":"Este preço está garantido?","r":"Não. As tarifas aéreas mudam conforme a disponibilidade. O valor mostrado é o encontrado na data da pesquisa e é confirmado pelo consultor no momento da sua solicitação."},{"p":"O que está incluído?","r":"Esta é uma oferta de passagem aérea de ida e volta para um adulto, em classe econômica. Hospedagem e outros serviços podem ser cotados à parte com o consultor."},{"p":"Posso mudar as datas?","r":"Sim. Informe as datas que você prefere e o consultor procura a melhor combinação disponível — o valor pode ser diferente do anunciado."},{"p":"Preciso de passaporte ou visto?","r":"As exigências de entrada mudam com frequência e dependem da sua nacionalidade. Nosso consultor confirma os documentos necessários antes da emissão."},{"p":"Como funciona o parcelamento?","r":"O valor pode ser dividido no cartão, conforme as condições vigentes no dia da emissão. O consultor informa as opções, inclusive para pagamento via Pix."}]'::jsonb) on conflict (destino_id) do nothing;
insert into destination_contents (destino_id,titulo_emocional,texto,motivos,faq) values ('porto','Porto: história, vinho e o Douro aos seus pés','Casas coloridas na Ribeira, o brilho do Douro e as caves de vinho do Porto formam um cenário romântico e acolhedor. Uma cidade para caminhar sem pressa e brindar cada descoberta.','["Ribeira e Ponte Dom Luís I","Caves históricas de vinho do Porto","Passeios pelo Vale do Douro","Fácil combinação com Lisboa na mesma viagem"]'::jsonb,'[{"p":"Este preço está garantido?","r":"Não. As tarifas aéreas mudam conforme a disponibilidade. O valor mostrado é o encontrado na data da pesquisa e é confirmado pelo consultor no momento da sua solicitação."},{"p":"O que está incluído?","r":"Esta é uma oferta de passagem aérea de ida e volta para um adulto, em classe econômica. Hospedagem e outros serviços podem ser cotados à parte com o consultor."},{"p":"Posso mudar as datas?","r":"Sim. Informe as datas que você prefere e o consultor procura a melhor combinação disponível — o valor pode ser diferente do anunciado."},{"p":"Preciso de passaporte ou visto?","r":"As exigências de entrada mudam com frequência e dependem da sua nacionalidade. Nosso consultor confirma os documentos necessários antes da emissão."},{"p":"Como funciona o parcelamento?","r":"O valor pode ser dividido no cartão, conforme as condições vigentes no dia da emissão. O consultor informa as opções, inclusive para pagamento via Pix."}]'::jsonb) on conflict (destino_id) do nothing;
insert into destination_contents (destino_id,titulo_emocional,texto,motivos,faq) values ('franca','Paris, para viver pelo menos uma vez','Museus, cafés, jardins e a luz única do fim de tarde às margens do Sena. Paris combina romance, cultura e compras como poucas cidades conseguem.','["Um dos destinos mais românticos do mundo","Museus e monumentos que atravessam séculos","Fácil conexão de trem com Londres, Bruxelas e o interior da França","Primavera e outono com clima agradável"]'::jsonb,'[{"p":"Este preço está garantido?","r":"Não. As tarifas aéreas mudam conforme a disponibilidade. O valor mostrado é o encontrado na data da pesquisa e é confirmado pelo consultor no momento da sua solicitação."},{"p":"O que está incluído?","r":"Esta é uma oferta de passagem aérea de ida e volta para um adulto, em classe econômica. Hospedagem e outros serviços podem ser cotados à parte com o consultor."},{"p":"Posso mudar as datas?","r":"Sim. Informe as datas que você prefere e o consultor procura a melhor combinação disponível — o valor pode ser diferente do anunciado."},{"p":"Preciso de passaporte ou visto?","r":"As exigências de entrada mudam com frequência e dependem da sua nacionalidade. Nosso consultor confirma os documentos necessários antes da emissão."},{"p":"Como funciona o parcelamento?","r":"O valor pode ser dividido no cartão, conforme as condições vigentes no dia da emissão. O consultor informa as opções, inclusive para pagamento via Pix."}]'::jsonb) on conflict (destino_id) do nothing;
